sys_script_client.script:
function onSubmit() {

    // 1. Rodar a validação APENAS se o campo for novo ou tiver mudado
    // (Use o nome correto do seu campo 'manager_base' aqui)
    if (g_form.isNewRecord() || g_form.isFieldModified('manager_base')) { 

        // 2. Use o API Name CORRETO que você encontrou antes
        var ga = new GlideAjax('x_1836079_office.BaseUtils');

        // 3. Mude de volta para 'checkDuplicateManager' (você pode apagar o 'pingTest' do Script Include)
        ga.addParam('sysparm_name', 'checkDuplicateManager'); 

        // 4. Adicione os parâmetros de volta
        ga.addParam('sysparm_manager_sysid', g_form.getValue('manager_base')); // <-- SEU CAMPO
        ga.addParam('sysparm_current_base_sysid', g_form.getUniqueValue());

        // 5. A GRANDE MUDANÇA: 
        // Em vez de 'getXMLWait()', usamos 'getXML()' e dizemos qual função rodar quando a resposta chegar.
        ga.getXML(validacaoCallback);

        // 6. PARE o envio do formulário por enquanto. A função 'validacaoCallback' decidirá o que fazer.
        return false; 
    }

    // 7. Se o campo NÃO mudou, não há nada para verificar. Deixe salvar.
    return true;
}

/**
 * 8. Esta é a nova função de "Callback". 
 * Ela roda QUANDO O SERVIDOR RESPONDER.
 */
function validacaoCallback(response) {
    // 9. Pega a resposta ('true' ou 'false') do Script Include
    var answer = response.responseXML.documentElement.getAttribute("answer");

    if (answer === 'true') {
        // 10. Se for duplicado, mostre o erro e NÃO FAÇA NADA.
        // O formulário continua parado.
        g_form.addErrorMessage('This manager is already assigned to another base. The submission has been canceled.');
		g_form.setValue('manager_base','');
    } else {
        // 11. Se for válido (false), envie o formulário de verdade!
        // g_form.submit() vai disparar o 'onSubmit' de novo, mas desta vez
        // ele cairá no passo 7 (pois o campo não mudou) e salvará.
        g_form.submit(g_form.getActionName());
    }
}
